const jiraFields = $('Jira > Get Issue').item.json.fields || {};
const jiraBrand = jiraFields.customfield_11504?.[0]?.value;
const jiraRegion = jiraFields.customfield_11507?.[0]?.value;

const rowData = $('Get Row from Baserow').item;
const row = rowData?.json || {};

if (!rowData || Object.keys(row).length === 0) {
  throw new Error(
    `[Baserow Query Error] No row found in table 541 for Jira_Brand_Code="${jiraBrand}" and Jira_Region="${jiraRegion}".`
  );
}

const brandCode = row.CMS_Brand_Code;
const brandName = row.CMS_Brand;
const bucket = row.CMS_Bucket;
const territory = row.MM_Territory;
const region = row.Jira_Region || jiraRegion;
const regionId = row.Region_ID;

const domain = row.Domain;
const bareDomain = domain
  ? String(domain).trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '')
  : undefined;

const pageUrl = bareDomain ? `https://www.${bareDomain}/` : undefined;
const loginUrl = bareDomain ? `https://services.${bareDomain}/services/login-service/v1/login` : undefined;
const cookieDomain = bareDomain ? `.${bareDomain}` : undefined;
const previewUrl = pageUrl ? `${pageUrl}account/messages` : undefined;

const casinoUsername = row.Email_Account;
const casinoPassword = row.Password;
const playerId = row.PLAYER_ID;
const audienceCode = row.AUDIENCE_CODE;

const missingFields = [];
if (!brandCode) missingFields.push('CMS_Brand_Code');
if (!brandName) missingFields.push('CMS_Brand');
if (!bucket) missingFields.push('CMS_Bucket');
if (!territory) missingFields.push('MM_Territory');
if (!regionId) missingFields.push('Region_ID');
if (!domain) missingFields.push('Domain');
if (!playerId) missingFields.push('PLAYER_ID');
if (!audienceCode) missingFields.push('AUDIENCE_CODE');
if (!casinoUsername) missingFields.push('Email_Account');
if (!casinoPassword) missingFields.push('Password');

if (missingFields.length > 0) {
  throw new Error(
    `[Baserow Mapping Error] Missing required fields (${missingFields.join(', ')}) for Jira_Brand_Code="${jiraBrand}", Jira_Region="${jiraRegion}".`
  );
}

const name = $('Naming Conventions API').item.json.name;
const slug = $('Naming Conventions API').item.json.slug;

const asCmsText = (raw) => String(raw ?? '').replace(/\u00a0/g, ' ').trim();
const readCmsTextField = (label, raw, { maxLen, required = false } = {}) => {
  const source = String(raw ?? '');
  const text = asCmsText(source);
  if (/[\r\n]/.test(source)) {
    throw new Error(
      maxLen != null
        ? `${label} must be plain text on one line, max ${maxLen} characters.`
        : `${label} must be plain text on one line.`
    );
  }
  if (/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/.test(source)) {
    throw new Error(`${label} must be plain text (no control characters).`);
  }
  if (required && !text) {
    throw new Error(`${label} is required.`);
  }
  if (maxLen != null && text.length > maxLen) {
    throw new Error(`${label} must be at most ${maxLen} characters (got ${text.length}).`);
  }
  return text;
};

const subject = readCmsTextField('Subject', jiraFields.customfield_26526, { maxLen: 50, required: true });
const notificationBody = readCmsTextField('Short copy', jiraFields.customfield_14907);
const notificationUrl = readCmsTextField('Notification URL', jiraFields.customfield_12423, { maxLen: 500 });
const notificationUrlLabel = readCmsTextField('CTA label', jiraFields.customfield_26527, { maxLen: 25 });

const wikiToHtml = (raw) => {
  const escapeHtml = (value) => String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  const applyWiki = (text) => {
    let s = text;
    s = s.replace(/\{color:[^}]+\}([\s\S]*?)\{color\}/gi, (_, inner) => {
      return `<span class="ol-Text--color_primary">${applyWiki(inner)}</span>`;
    });
    s = s.replace(/\{\*\}([\s\S]*?)\{\*\}/g, (_, inner) => `<strong>${applyWiki(inner)}</strong>`);
    s = s.replace(/\{_\}([\s\S]*?)\{_\}/g, (_, inner) => `<em>${applyWiki(inner)}</em>`);
    s = s.replace(/\{\^\}([\s\S]*?)\{\^\}/g, (_, inner) => `<sup>${applyWiki(inner)}</sup>`);
    s = s.replace(/\{\~\}([\s\S]*?)\{\~\}/g, (_, inner) => `<sub>${applyWiki(inner)}</sub>`);
    s = s.replace(/\[([^\]\n|]+)\|([^\]\n|]+)(?:\|[^\]]+)?\]/g, '<a href="$2">$1</a>');
    s = s.replace(/\[(https?:\/\/[^\]\n]+)\]/g, '<a href="$1">$1</a>');
    s = s.replace(/\*([^*\n]+)\*/g, '<strong>$1</strong>');
    s = s.replace(/_([^_\n]+)_/g, '<em>$1</em>');
    s = s.replace(/\^([^\^\n]+)\^/g, '<sup>$1</sup>');
    s = s.replace(/~([^~\n]+)~/g, '<sub>$1</sub>');
    s = s.replace(/\n/g, '<br>');
    return s;
  };

  const source = String(raw ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  return applyWiki(escapeHtml(source));
};

const messageBodyHtml = wikiToHtml(jiraFields.customfield_26522);

const IMAGE_EXT = /\.(webp|png|jpe?g|gif|bmp|svg|avif|tiff?|heic|heif|ico|jfif|pjpeg|pjp|apng|jxl)$/i;
const isImageAttachment = (a) => {
  const mime = String(a?.mimeType || '').toLowerCase();
  const filename = String(a?.filename || '');
  return mime.startsWith('image/') || IMAGE_EXT.test(filename);
};
const isWebpAttachment = (a) => {
  const mime = String(a?.mimeType || '').toLowerCase();
  const filename = String(a?.filename || '').toLowerCase();
  return mime === 'image/webp' || filename.endsWith('.webp');
};
const attachments = Array.isArray(jiraFields.attachment) ? jiraFields.attachment : [];
const imageAttachments = attachments.filter(isImageAttachment);
const webpAttachments = imageAttachments.filter(isWebpAttachment);
// Jira lists newest first; last image is the original creative. Prefer webp over later comment screenshots.
const preferredImages = webpAttachments.length ? webpAttachments : imageAttachments;
const imageAttachment = preferredImages.length ? preferredImages[preferredImages.length - 1] : null;
const imageAttachmentId = imageAttachment?.id ? String(imageAttachment.id) : '';

return {
  sessionId: $('CMS & MM Login').item.json.sessionId,
  name,
  slug,
  region,
  regionId,
  brandName,
  brandCode,
  bucket,
  territory,
  pageUrl,
  loginUrl,
  cookieDomain,
  previewUrl,
  playerId,
  audienceCode,
  subject,
  notificationBody,
  notificationUrl,
  notificationUrlLabel,
  imageAttachmentId,
  messageBodyHtml,
};

