={{ (() => {
  const username = $('Get Row from Baserow').item.json.Email_Account;
  const password = $('Get Row from Baserow').item.json.Password;
  const pageUrl = $('OSN Static Fields Mapping').item.json.pageUrl;
  if (!username || !password || !pageUrl) {
    throw new Error('Casino browser login missing username, password, or pageUrl');
  }
  const base = String(pageUrl).replace(//?$/, '/');
  const loginPage = base.includes('ignitionpoker.com') ? base + 'en/login' : base + 'login';
  return `export default async ({ page }) => {
  const username = ${JSON.stringify(username)};
  const password = ${JSON.stringify(password)};
  const loginPage = ${JSON.stringify(loginPage)};
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  const acceptCookies = async () => page.evaluate(() => {
    const accept = document.querySelector('.coi-banner__accept, button[class*="coi-banner__accept"]');
    if (!accept) return false;
    accept.click();
    return true;
  });

  const fillReactInput = async (selector, value) => page.evaluate((sel, val) => {
    const el = [...document.querySelectorAll(sel)].find((n) => n.offsetWidth > 0 && n.offsetHeight > 0) || document.querySelector(sel);
    if (!el) throw new Error('Missing login field ' + sel);
    el.focus();
    const proto = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
    const last = el.value;
    proto.set.call(el, '');
    if (el._valueTracker) el._valueTracker.setValue(last);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    proto.set.call(el, val);
    if (el._valueTracker) el._valueTracker.setValue('');
    el.dispatchEvent(new InputEvent('input', { bubbles: true, data: val, inputType: 'insertText' }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    el.blur();
  }, selector, value);

  const fieldsMatch = async () => page.evaluate((user, pass) => {
    const u = document.querySelector('#username');
    const p = document.querySelector('#password');
    const btn = document.querySelector('#loginSubmit');
    return !!(u && p && btn && u.value === user && p.value === pass && !btn.disabled);
  }, username, password);

  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36');
  await page.evaluateOnNewDocument(() => {
    Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
  });
  await page.setViewport({ width: 1440, height: 900 });
  await page.goto(loginPage, { waitUntil: 'domcontentloaded', timeout: 20000 });
  await page.waitForSelector('#username', { visible: true, timeout: 15000 });

  try {
    await page.waitForFunction(() => {
      const btn = document.querySelector('#loginSubmit');
      return !!(btn && !btn.disabled);
    }, { timeout: 12000 });
  } catch (err) {
    void err;
  }

  try {
    await page.waitForFunction(() => window.grecaptcha && typeof window.grecaptcha.execute === 'function', { timeout: 12000 });
  } catch (err) {
    void err;
  }

  try {
    await page.waitForSelector('.coi-banner__accept', { timeout: 12000 });
    await acceptCookies();
    await sleep(800);
  } catch (err) {
    void err;
  }

  await fillReactInput('#username', username);
  await fillReactInput('#password', password);
  await sleep(200);
  if (!(await fieldsMatch())) {
    await fillReactInput('#username', username);
    await fillReactInput('#password', password);
    await sleep(200);
  }
  if (!(await fieldsMatch())) {
    throw new Error('Casino login fields did not keep the Baserow credentials after fill');
  }

  const loginWait = page.waitForResponse(
    (response) => response.url().includes('/login-service/v1/login') && response.request().method() === 'POST',
    { timeout: 20000 }
  );
  await page.click('#loginSubmit');

  let response;
  try {
    response = await loginWait;
  } catch (err) {
    throw new Error('Casino login POST never fired');
  }

  const body = await response.json().catch(() => null);
  if (!body || !body.sessionId) {
    throw new Error('Casino browser login did not return sessionId: ' + JSON.stringify({ status: response.status(), errorCode: body && body.errorCode }));
  }
  return { data: { sessionId: body.sessionId }, type: 'application/json' };
};`;
})() }}

