attachments.text:
={{ (() => {
  const b = (s) => String.fromCharCode(42, 42) + s + String.fromCharCode(42, 42);
  let runData = {};
  try { runData = $('Get Failed Execution').item.json.data.resultData.runData || {}; } catch (e) {}
  const firstJson = (name) => (runData[name] || [])[0]?.data?.main?.[0]?.[0]?.json;
  const cmsCreated = (runData['CMS > Create Notification'] || []).some((r) => r.executionStatus === 'success');
  const assignee = (firstJson('Jira > Get Issue') || {}).fields?.assignee?.name;
  const norm = firstJson('Normalize Webhook Input') || {};
  const jira = firstJson('Jira > Get Issue') || {};
  const mapTicket = norm.mapTicket || jira.key || '';
  const docname = norm.erpnextDocname || '';
  const mapping = firstJson('OSN Static Fields Mapping') || {};
  const check = firstJson('CMS > Check Existing Slug') || {};
  const created = firstJson('CMS > Get ContentId By Slug') || {};
  const createJson = firstJson('CMS > Create Notification') || {};
  const wanted = (firstJson('Naming Conventions API') || {}).slug;
  const checkItems = check.items || [];
  const checkHit = checkItems.find((item) => {
    const slug = item.fields?.nonLocalised?.slugname || item.indexed?.slugname;
    return wanted && slug === wanted;
  }) || checkItems[0] || {};
  const createdHit = (created.items || [])[0] || {};
  const cmsHref = (contentId, bucket) => {
    if (!mapping.brandCode || !contentId) return '';
    return 'https://contentmanager.intra-apps.com/content/edit/notification/' + mapping.brandCode + '/' + String(bucket || mapping.bucket || '').toLowerCase() + '/' + contentId;
  };
  const err = $('On Workflow Error').item.json.execution || {};
  const errObj = err.error || {};
  let reason = String(errObj.stack || '').split('\n')[0].replace(/^Error:\s*/i, '').trim();
  reason = reason.replace(/\[line \d+\]/gi, '').replace(/\s+/g, ' ').trim();
  if (!reason || reason.startsWith('//') || reason === 'https') {
    reason = String(errObj.message || 'n8n workflow failed').replace(/\[line \d+\]/gi, '').trim();
  }
  const duplicate = /already exists/i.test(reason) || err.lastNodeExecuted === 'Notification already exists';
  if (cmsCreated) {
    reason = 'Automation not able to get the proof';
    const contentId = createdHit.contentId || createJson.contentId || createJson.id;
    const cmsUrl = cmsHref(contentId, createdHit.bucket || mapping.bucket);
    if (cmsUrl) reason += ' - [Open in CMS](' + cmsUrl + ')';
  } else if (duplicate) {
    reason = 'Notification already exists';
    const cmsUrl = cmsHref(checkHit.contentId, mapping.bucket);
    if (cmsUrl) reason += ' - [Open in CMS](' + cmsUrl + ')';
  }
  const lines = [];
  if (assignee) lines.push(b('Assignee:') + ' @' + assignee);
  if (mapTicket) {
    lines.push(b('MAP:') + ' [' + mapTicket + '](https://jiraops.corp-apps.com/browse/' + mapTicket + ')');
  }
  if (docname) {
    lines.push(b('MarDesk:') + ' [' + docname + '](https://martech-desk.corp-apps.com/app/n8n-workflow-run/' + docname + ')');
  }
  lines.push(b('Reason:') + ' ' + reason);
  return lines.join('\n');
})() }}

